// Run: node contract/build.mjs
// Generates what the web page loads (fetch() is refused on file:// in the desktop app, so the contracts ship as plain scripts):
//   nav-contract.js    <- nav-contract.json   (the one navigation, also read by Android)
//   theme-contract.js  <- themes.json + theme-schemes.json   (the six themes, also read by Android)
// and rewrites the two generated theme blocks inside index.html (see theme-css.mjs). The tonal palettes themselves are generated by
// contract/build-themes.mjs (it needs the dev dependency). The contract tests fail if any of these drift.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadEngine, fallbackBlock, panelsBlock, swap, FALLBACK, PANELS } from './theme-css.mjs';
const dir = path.dirname(fileURLToPath(import.meta.url));
const read = (f) => JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'));
fs.writeFileSync(path.join(dir, 'nav-contract.js'), `// GENERATED from nav-contract.json by contract/build.mjs. Do not edit.\nwindow.COCO_NAV = ${JSON.stringify(read('nav-contract.json'))};\n`);
const { contract, E } = loadEngine();
fs.writeFileSync(path.join(dir, 'theme-contract.js'), `// GENERATED from themes.json + theme-schemes.json by contract/build.mjs. Do not edit.\nwindow.COCO_THEMES = ${JSON.stringify(contract)};\n`);
const indexPath = path.join(dir, '..', 'index.html');
let html = fs.readFileSync(indexPath, 'utf8');
if (html.includes(FALLBACK.start)) { html = swap(html, FALLBACK, fallbackBlock(E)); html = swap(html, PANELS, panelsBlock(E)); fs.writeFileSync(indexPath, html); console.log('index.html theme blocks regenerated'); }
console.log('nav-contract.js and theme-contract.js written');
